require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE','AGENT']);$db=Database::connection();$id=(int)($_GET['id']??0);$s=$db->prepare("SELECT d.numero_demande,d.date_demande,cr.libelle categorie,COALESCE(c.raison_sociale,CONCAT(c.prenom,' ',c.nom)) client FROM demandes_devis d JOIN clients c ON c.id=d.client_id JOIN categories_risque cr ON cr.id=d.categorie_id WHERE d.id=?");$s->execute([$id]);$d=$s->fetch()?:exit('Demande introuvable.');$s=$db->prepare("SELECT co.raison_sociale,p.nom,o.* FROM offres_devis o JOIN produits_assurance p ON p.id=o.produit_id JOIN compagnies co ON co.id=p.compagnie_id WHERE o.demande_id=? ORDER BY o.score_global DESC");$s->execute([$id]);$rows=$s->fetchAll();audit('IMPRESSION_PDF','demande_devis',$id);?><!doctype html><html lang="fr"><head><meta charset="utf-8"><title>Devis <?= e($d['numero_demande']) ?></title><style>body{font-family:Arial;color:#172033;margin:35px}header{border-bottom:3px solid #17345f;padding-bottom:15px}h1{color:#17345f}table{width:100%;border-collapse:collapse;margin-top:25px}th,td{border:1px solid #ccd4df;padding:10px;text-align:left}th{background:#eaf2fb}.best{background:#fff6d8}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Imprimer / Enregistrer en PDF</button><header><h1>AssurCourt</h1><strong>Devis comparatif multi-compagnies</strong></header><p>Demande : <?= e($d['numero_demande']) ?><br>Client : <?= e($d['client']) ?><br>Branche : <?= e($d['categorie']) ?></p><table><thead><tr><th>Rang</th><th>Compagnie</th><th>Produit</th><th>Prime nette</th><th>Total annuel</th><th>Score</th></tr></thead><tbody><?php foreach($rows as $i=>$r): ?><tr class="<?= $i===0?'best':'' ?>"><td><?= $i+1 ?></td><td><?= e($r['raison_sociale']) ?></td><td><?= e($r['nom']) ?></td><td><?= number_format((float)$r['prime_nette'],0,',',' ') ?></td><td><?= number_format((float)$r['prime_totale'],0,',',' ') ?> FCFA</td><td><?= e((string)$r['score_global']) ?>/100</td></tr><?php endforeach ?></tbody></table><p><small>Document généré par AssurCourt.</small></p></body></html>
